import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Define the routes and methods that require role-based access control
  const protectedRoutes = [
    { path: "/drive", method: "POST" },
    { path: "/applications", method: "GET" }
  ];

  // Check if the current request matches any protected route
  const isProtectedRoute = protectedRoutes.some(route => route.path === req.path && route.method === req.method);

  if (!isProtectedRoute) {
    // If the request is not a protected route, proceed to the next middleware
    return next();
  }

  // For demonstration purposes, assume we have a user role in the request headers
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    // If no user role is provided, deny access
    res.status(403).send("Forbidden: User role required.");
    return;
  }

  // Define the roles and their permissions
  const companyRoles = ["company"];
  const studentRoles = ["student"];

  if ((req.method === "POST" && !companyRoles.includes(userRole)) ||
      (req.method === "GET" && !studentRoles.includes(userRole))) {
    // Deny access based on the user's role
    res.status(403).send(`Forbidden: ${userRole} users are not allowed to perform this action.`);
    return;
  }

  // If the user has the correct role, proceed to the next middleware
  next();
}

